def dos_suma_fuerza_bruta(nums, objetivo):
    """O(n²) en tiempo y O(1) en memoria: correcta y buen punto de partida."""
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == objetivo:
                return i, j
    return None


def dos_suma(nums, objetivo):
    """O(n) en tiempo y memoria: un dict recuerda lo ya visto."""
    vistos = {}                       # valor -> índice
    for i, x in enumerate(nums):
        if objetivo - x in vistos:
            return vistos[objetivo - x], i
        vistos[x] = i
    return None


# Probar en voz alta: caso normal, duplicados, negativos y sin solución
for f in (dos_suma_fuerza_bruta, dos_suma):
    assert f([2, 7, 11, 15], 9) == (0, 1)
    assert f([3, 3], 6) == (0, 1)
    assert f([-1, 5, 4], 3) == (0, 2)
    assert f([1, 2], 10) is None
