def fusionar_intervalos(intervalos):
    """Fusiona intervalos cerrados que se solapan o se tocan."""
    pares = []
    for par in intervalos:
        inicio, fin = par
        if inicio > fin:
            raise ValueError(f"intervalo inválido: {par!r}")
        pares.append((inicio, fin))

    pares.sort()
    resultado = []
    for inicio, fin in pares:
        if resultado and inicio <= resultado[-1][1]:
            ultimo_inicio, ultimo_fin = resultado[-1]
            resultado[-1] = (ultimo_inicio, max(ultimo_fin, fin))
        else:
            resultado.append((inicio, fin))
    return resultado

