def justificar(texto, ancho):
    """Devuelve las líneas del texto justificadas a 'ancho' caracteres."""
    if ancho <= 0:
        raise ValueError("el ancho debe ser positivo")
    palabras = texto.split()
    for palabra in palabras:
        if len(palabra) > ancho:
            raise ValueError(f"la palabra {palabra!r} no cabe en {ancho} caracteres")

    lineas = []
    actual = []
    letras = 0  # caracteres de las palabras de la línea actual, sin espacios
    for palabra in palabras:
        # con k palabras hay k huecos si añadimos una más
        if actual and letras + len(actual) + len(palabra) > ancho:
            lineas.append(_repartir(actual, letras, ancho))
            actual, letras = [], 0
        actual.append(palabra)
        letras += len(palabra)
    if actual:
        lineas.append(" ".join(actual).ljust(ancho))
    return lineas


def _repartir(palabras, letras, ancho):
    """Construye una línea justificada (no la última)."""
    if len(palabras) == 1:
        return palabras[0].ljust(ancho)
    huecos = len(palabras) - 1
    base, extra = divmod(ancho - letras, huecos)
    partes = []
    for i, palabra in enumerate(palabras[:-1]):
        partes.append(palabra)
        partes.append(" " * (base + (1 if i < extra else 0)))
    partes.append(palabras[-1])
    return "".join(partes)

