def aplanar(estructura):
    """Produce los elementos no contenedores de listas/tuplas anidadas."""
    yield from _aplanar(estructura, set())


def _aplanar(nodo, en_camino):
    if not isinstance(nodo, (list, tuple)):
        yield nodo
        return
    if id(nodo) in en_camino:
        raise ValueError("ciclo detectado")
    en_camino.add(id(nodo))
    try:
        for hijo in nodo:
            yield from _aplanar(hijo, en_camino)
    finally:
        en_camino.discard(id(nodo))

