class Matriz:
    """Matriz numérica inmutable."""

    def __init__(self, filas):
        datos = tuple(tuple(fila) for fila in filas)
        if not datos or not datos[0]:
            raise ValueError("la matriz no puede estar vacía")
        ancho = len(datos[0])
        if any(len(fila) != ancho for fila in datos):
            raise ValueError("todas las filas deben tener la misma longitud")
        self._datos = datos

    @classmethod
    def identidad(cls, n):
        return cls([[1 if i == j else 0 for j in range(n)] for i in range(n)])

    @property
    def forma(self):
        return len(self._datos), len(self._datos[0])

    def __len__(self):
        return len(self._datos)

    def __iter__(self):
        return iter(self._datos)

    def __getitem__(self, indice):
        if isinstance(indice, tuple):
            i, j = indice
            return self._datos[i][j]
        return self._datos[indice]

    def __repr__(self):
        return f"Matriz({[list(fila) for fila in self._datos]})"

    def __eq__(self, otra):
        if not isinstance(otra, Matriz):
            return NotImplemented
        return self._datos == otra._datos

    def __hash__(self):
        return hash(self._datos)

    def __add__(self, otra):
        if not isinstance(otra, Matriz):
            return NotImplemented
        if self.forma != otra.forma:
            raise ValueError(f"formas incompatibles: {self.forma} y {otra.forma}")
        return Matriz([[a + b for a, b in zip(f1, f2)] for f1, f2 in zip(self, otra)])

    def __mul__(self, k):
        if not isinstance(k, (int, float)):
            return NotImplemented
        return Matriz([[k * x for x in fila] for fila in self])

    __rmul__ = __mul__

    def __matmul__(self, otra):
        if not isinstance(otra, Matriz):
            return NotImplemented
        if self.forma[1] != otra.forma[0]:
            raise ValueError(f"no se puede multiplicar {self.forma} por {otra.forma}")
        columnas = list(zip(*otra))
        return Matriz([[sum(a * b for a, b in zip(fila, col)) for col in columnas] for fila in self])

    def transpuesta(self):
        return Matriz(zip(*self._datos))

