def _camino_valido(mapa, camino):
    """Comprueba que el camino va de S a E por casillas libres y adyacentes."""
    if not camino:
        return False
    (f0, c0), (f1, c1) = camino[0], camino[-1]
    if mapa[f0][c0] != "S" or mapa[f1][c1] != "E":
        return False
    for (fa, ca), (fb, cb) in zip(camino, camino[1:]):
        if abs(fa - fb) + abs(ca - cb) != 1:
            return False
        if not (0 <= fb < len(mapa) and 0 <= cb < len(mapa[0])) or mapa[fb][cb] == "#":
            return False
    return len(set(camino)) == len(camino)

