from collections import deque


def camino_mas_corto(mapa):
    """Camino mínimo de S a E con búsqueda en anchura (BFS)."""
    if not mapa or any(len(fila) != len(mapa[0]) for fila in mapa):
        raise ValueError("el mapa debe ser rectangular y no vacío")
    inicios = [(f, c) for f, fila in enumerate(mapa) for c, x in enumerate(fila) if x == "S"]
    metas = [(f, c) for f, fila in enumerate(mapa) for c, x in enumerate(fila) if x == "E"]
    if len(inicios) != 1 or len(metas) != 1:
        raise ValueError("debe haber exactamente una S y una E")
    inicio, meta = inicios[0], metas[0]
    alto, ancho = len(mapa), len(mapa[0])

    previo = {inicio: None}
    cola = deque([inicio])
    while cola:
        actual = cola.popleft()
        if actual == meta:
            camino = []
            while actual is not None:
                camino.append(actual)
                actual = previo[actual]
            return camino[::-1]
        f, c = actual
        for df, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            vecino = (f + df, c + dc)
            nf, nc = vecino
            if 0 <= nf < alto and 0 <= nc < ancho and mapa[nf][nc] != "#" and vecino not in previo:
                previo[vecino] = actual
                cola.append(vecino)
    return None

