import asyncio


class Monitor:
    """Crea fábricas de trabajos y registra cuántos se ejecutan a la vez."""

    def __init__(self):
        self.activos = 0
        self.maximo = 0
        self.creadas = 0

    def fabrica(self, valor, espera=0.01, error=None):
        async def trabajo():
            self.activos += 1
            self.maximo = max(self.maximo, self.activos)
            try:
                await asyncio.sleep(espera)
                if error is not None:
                    raise error
                return valor
            finally:
                self.activos -= 1

        def crear():
            self.creadas += 1
            return trabajo()

        return crear

