import functools
import inspect
import types


def _comprobable(anotacion):
    """Solo se validan clases y uniones de clases (int | None)."""
    if anotacion is inspect.Parameter.empty:  # sin anotación (¡empty también es una clase!)
        return False
    return isinstance(anotacion, (type, types.UnionType))


def _nombre(anotacion):
    return anotacion.__name__ if isinstance(anotacion, type) else str(anotacion)


def validar_tipos(funcion):
    firma = inspect.signature(funcion)

    @functools.wraps(funcion)
    def envoltura(*args, **kwargs):
        ligados = firma.bind(*args, **kwargs)
        ligados.apply_defaults()
        for nombre, valor in ligados.arguments.items():
            parametro = firma.parameters[nombre]
            if parametro.kind in (parametro.VAR_POSITIONAL, parametro.VAR_KEYWORD):
                continue
            anotacion = parametro.annotation
            if _comprobable(anotacion) and not isinstance(valor, anotacion):
                raise TypeError(
                    f"{nombre} debe ser {_nombre(anotacion)}, no {type(valor).__name__}"
                )
        resultado = funcion(*args, **kwargs)
        retorno = firma.return_annotation
        if _comprobable(retorno) and not isinstance(resultado, retorno):
            raise TypeError(
                f"el valor de retorno debe ser {_nombre(retorno)}, no {type(resultado).__name__}"
            )
        return resultado

    return envoltura

